function normalizeAccessoryId(itemId) {
    if (!itemId) return null;
    if (MASCOT_ACCESSORY_CATALOG.some((item) => item.id === itemId)) return itemId;
    const aliased = MASCOT_ACCESSORY_ID_ALIASES[itemId];
    if (aliased === null) return null;
    if (aliased && MASCOT_ACCESSORY_CATALOG.some((item) => item.id === aliased)) return aliased;
    return null;
}

function getAccessoryCatalogItem(itemId) {
    const normalized = normalizeAccessoryId(itemId);
    return MASCOT_ACCESSORY_CATALOG.find((item) => item.id === normalized) || null;
}

function getMascotLiveRoot() {
    return document.querySelector('#tm-mascot-container[data-tm-mascot-live="1"]')
        || document.querySelector('#tm-mascot-container:not([data-tm-ui-shell="1"])')
        || document.getElementById('tm-mascot-container');
}

function setMascotAccessoryVisible(el, visible) {
    if (!el) return;
    // Never touch page DOM outside the live mascot (service_edit has colliding #book/#shield/etc.)
    const root = getMascotLiveRoot();
    if (root && !root.contains(el)) return;
    if (visible) el.style.removeProperty('display');
    else el.style.display = 'none';
}

function hideAllMascotAccessories() {
    const root = getMascotLiveRoot();
    if (!root) return;
    root.querySelectorAll('.tm-mascot-accessory').forEach((el) => {
        setMascotAccessoryVisible(el, false);
        el.classList.remove('tm-accessory-equipped');
    });
}

function showMascotAccessory(itemId) {
    const el = getAccessoryElement(itemId);
    if (!el) return false;
    el.classList.add('tm-accessory-equipped');
    layoutMascotAccessory(itemId, tamagotchiStage);
    setMascotAccessoryVisible(el, true);
    return true;
}

function migrateAccessoryStorage(STORAGE_KEYS) {
    if (!STORAGE_KEYS?.PURCHASED_ITEMS || !STORAGE_KEYS?.EQUIPPED_ITEMS) return;

    // PURCHASED_ITEMS holds accessories AND themes/features.
    // Only normalize/drop accessory IDs — never strip theme/feature IDs.
    const migratePurchased = (list) => {
        const out = [];
        const seen = new Set();
        for (const rawId of (Array.isArray(list) ? list : [])) {
            if (!rawId) continue;
            const asAccessory = normalizeAccessoryId(rawId);
            let next = rawId;
            if (asAccessory) {
                next = asAccessory;
            } else if (Object.prototype.hasOwnProperty.call(MASCOT_ACCESSORY_ID_ALIASES, rawId)) {
                // Known removed accessory alias → drop
                continue;
            }
            // else keep themes / features / other non-accessory ids
            if (seen.has(next)) continue;
            seen.add(next);
            out.push(next);
        }
        return out;
    };

    // EQUIPPED_ITEMS is accessories-only.
    const migrateEquipped = (list) => [...new Set(
        (Array.isArray(list) ? list : [])
            .map(normalizeAccessoryId)
            .filter(Boolean)
    )];

    const purchased = migratePurchased(JSON.parse(GM_getValue(STORAGE_KEYS.PURCHASED_ITEMS, '[]')));
    const equipped = migrateEquipped(JSON.parse(GM_getValue(STORAGE_KEYS.EQUIPPED_ITEMS, '[]')));

    GM_setValue(STORAGE_KEYS.PURCHASED_ITEMS, JSON.stringify(purchased));
    GM_setValue(STORAGE_KEYS.EQUIPPED_ITEMS, JSON.stringify(equipped));
}

function getEffectiveMascotStage() {
    return (mascotStagePreviewLock && mascotStagePreviewStage) ? mascotStagePreviewStage : tamagotchiStage;
}

function clearMascotStagePreview(restore = true) {
    if (mascotStagePreviewTimeout) {
        clearTimeout(mascotStagePreviewTimeout);
        mascotStagePreviewTimeout = null;
    }
    mascotStagePreviewLock = false;
    mascotStagePreviewStage = null;
    if (restore && document.getElementById('tm-mascot-container')) {
        updateMascotAppearanceByStage(tamagotchiStage);
    }
}

function previewMascotStage(stage, durationMs = 5000) {
    if (!stage || !document.getElementById('tm-mascot-container')) return false;

    if (mascotStagePreviewTimeout) {
        clearTimeout(mascotStagePreviewTimeout);
        mascotStagePreviewTimeout = null;
    }

    mascotStagePreviewLock = true;
    mascotStagePreviewStage = stage;
    updateMascotAppearanceByStage(stage);

    if (durationMs > 0) {
        mascotStagePreviewTimeout = setTimeout(() => clearMascotStagePreview(true), durationMs);
    }
    return true;
}

/**
 * Debug helper: permanently set the active mascot character and refresh the sprite.
 * If still an egg, advances to baby so the chosen character is visible.
 */
function debugSetMascotCharacter(characterType, STORAGE_KEYS) {
    if (!characterType || !TAMA_CHARACTER_TYPES.includes(characterType)) return false;

    cancelTamagotchiCinematics();
    clearMascotStagePreview(false);

    tamagotchiCharacterType = characterType;
    tamagotchiIsDead = false;

    if (tamagotchiStage === 'egg' || tamagotchiLifeMinutes < TAMA_STAGE_MINUTES.evo1) {
        tamagotchiLifeMinutes = Math.max(Number(tamagotchiLifeMinutes) || 0, TAMA_STAGE_MINUTES.evo1);
        tamagotchiStage = 'evo1';
        tamagotchiEggHatchCinematicDone = true;
    } else {
        tamagotchiStage = getTamagotchiStageFromLifeMinutes(tamagotchiLifeMinutes);
    }

    syncTamagotchiLifeMinutes();
    noteMascotEvolutionReached(tamagotchiStage, tamagotchiCharacterType);
    const keys = getTamagotchiStorageKeys(
        STORAGE_KEYS || (typeof window.STORAGE_KEYS !== 'undefined' ? window.STORAGE_KEYS : null),
    );
    if (keys) saveTamagotchiData(keys);

    updateMascotAppearanceByStage(tamagotchiStage);
    if (typeof updateTamagotchiPersonality === 'function') {
        try { updateTamagotchiPersonality(); } catch { /* ignore */ }
    }

    console.log(`[Mascot] Debug character set to ${characterType} (stage ${tamagotchiStage})`);
    return true;
}

/** Life stages in evolution order (egg → … → old). */
const TAMA_LIFE_STAGE_ORDER = ['egg', 'evo1', 'evo2', 'evo3'];

/** Maps life stage → SVG sprite group key (`tm-mascot-{key}-{character}`). */
const TAMA_STAGE_TO_SPRITE_KEY = {
    egg: 'base',
    evo1: 'evo1',
    evo2: 'evo2',
    evo3: 'evo3',
};

/** Migrate legacy age-stage names → 3-evolution line. */
function migrateLifeStageName(stage) {
    const map = {
        egg: 'egg',
        baby: 'evo1',
        kid: 'evo1',
        teen: 'evo2',
        adult: 'evo2',
        middleage: 'evo3',
        old: 'evo3',
        evo1: 'evo1',
        evo2: 'evo2',
        evo3: 'evo3',
    };
    return map[stage] || 'egg';
}

/** Highest stage reached in the current egg cycle. */
let tamagotchiMaxReachedStage = 'egg';
/**
 * Lifetime discovery map: characterType → highest stage ever reached with that character.
 * Survives egg resets so Evolution Preview can unlock previously seen forms.
 */
let tamagotchiEvolutionDiscovery = {};

function getMascotLifeStageIndex(stage) {
    const idx = TAMA_LIFE_STAGE_ORDER.indexOf(stage);
    return idx >= 0 ? idx : -1;
}

function maxMascotLifeStage(a, b) {
    return getMascotLifeStageIndex(a) >= getMascotLifeStageIndex(b) ? (a || 'egg') : (b || 'egg');
}

function normalizeEvolutionDiscovery(raw) {
    const out = {};
    if (!raw || typeof raw !== 'object') return out;
    Object.keys(raw).forEach((char) => {
        if (!TAMA_CHARACTER_TYPES.includes(char)) return;
        const stage = migrateLifeStageName(raw[char]);
        if (TAMA_LIFE_STAGE_ORDER.includes(stage)) {
            out[char] = stage;
        }
    });
    return out;
}

function mergeEvolutionDiscoveryMaps(a, b) {
    const out = { ...normalizeEvolutionDiscovery(a) };
    const other = normalizeEvolutionDiscovery(b);
    Object.keys(other).forEach((char) => {
        out[char] = maxMascotLifeStage(out[char] || 'egg', other[char]);
    });
    return out;
}

/**
 * Highest evolution the user has unlocked for Evolution Preview.
 * Prefer lifetime discovery for the character; also count the current life if same type.
 */
function getMaxReachedEvolution(characterType = tamagotchiCharacterType) {
    if (!characterType || characterType === 'none') {
        return maxMascotLifeStage(tamagotchiMaxReachedStage || 'egg', 'egg');
    }
    let max = tamagotchiEvolutionDiscovery[characterType] || 'egg';
    if (tamagotchiCharacterType === characterType) {
        max = maxMascotLifeStage(max, tamagotchiMaxReachedStage);
        max = maxMascotLifeStage(max, tamagotchiStage);
    }
    return max;
}

function isMascotStageUnlockedForPreview(stage, characterType = tamagotchiCharacterType) {
    if (stage === 'egg') return true;
    if (!characterType || characterType === 'none') return false;
    return getMascotLifeStageIndex(stage) <= getMascotLifeStageIndex(getMaxReachedEvolution(characterType));
}

function getMascotSpriteIdForStage(stage, characterType) {
    if (stage === 'egg') return 'tm-mascot-base';
    const key = TAMA_STAGE_TO_SPRITE_KEY[stage] || 'evo1';
    if (!characterType || characterType === 'none') return `tm-mascot-${key}`;
    return `tm-mascot-${key}-${characterType}`;
}

/** Record progression for the current life + lifetime discovery book. */
function noteMascotEvolutionReached(stage, characterType = tamagotchiCharacterType) {
    if (!stage || !TAMA_LIFE_STAGE_ORDER.includes(stage)) return;
    tamagotchiMaxReachedStage = maxMascotLifeStage(tamagotchiMaxReachedStage, stage);
    if (characterType && characterType !== 'none' && TAMA_CHARACTER_TYPES.includes(characterType)) {
        const prev = tamagotchiEvolutionDiscovery[characterType] || 'egg';
        tamagotchiEvolutionDiscovery[characterType] = maxMascotLifeStage(prev, stage);
    }
}

/**
 * Debug: jump lifeMinutes to the next stage threshold and run the real evolution path
 * (sprite swap + bubble + character cinematic when applicable).
 * @returns {{ ok: boolean, from?: string, to?: string, reason?: string }}
 */
function debugAdvanceMascotEvolution(STORAGE_KEYS) {
    if (tamagotchiIsDead) {
        return { ok: false, reason: 'dead' };
    }
    if (tamaCinematicLock) {
        return { ok: false, reason: 'cinematic' };
    }

    refreshTamaLifespanScale();
    const from = getTamagotchiStageFromLifeMinutes(tamagotchiLifeMinutes);
    const idx = TAMA_LIFE_STAGE_ORDER.indexOf(from);
    if (idx < 0 || idx >= TAMA_LIFE_STAGE_ORDER.length - 1) {
        return { ok: false, reason: 'max', from };
    }

    const to = TAMA_LIFE_STAGE_ORDER[idx + 1];
    const need = Number(TAMA_STAGE_MINUTES[to]);
    if (!Number.isFinite(need)) {
        return { ok: false, reason: 'threshold', from, to };
    }

    cancelTamagotchiCinematics();
    clearMascotStagePreview(false);

    // Land just at the stage floor so getTamagotchiStageFromLifeMinutes → `to`
    tamagotchiLifeMinutes = Math.max(Number(tamagotchiLifeMinutes) || 0, need);
    tamagotchiLastUpdate = Date.now();
    tamagotchiIsDead = false;
    if (to !== 'egg') {
        // Ensure hatch cinematic is considered done when skipping past egg via debug
        if (from === 'egg') {
            // Let checkTamagotchiEvolution run the hatch path naturally
            tamagotchiEggHatchCinematicDone = false;
        }
    }
    const keys = getTamagotchiStorageKeys(
        STORAGE_KEYS || (typeof window.STORAGE_KEYS !== 'undefined' ? window.STORAGE_KEYS : null),
    );
    const container = getMascotLiveRoot() || document.getElementById('tm-mascot-container');
    if (container) {
        checkTamagotchiEvolution(container);
    } else {
        tamagotchiStage = getTamagotchiStageFromLifeMinutes(tamagotchiLifeMinutes);
        if (keys) saveTamagotchiData(keys);
    }
    if (keys) saveTamagotchiData(keys);

    console.log(`[Mascot] Debug evolution: ${from} → ${tamagotchiStage} (life=${Math.round(tamagotchiLifeMinutes)})`);
    return { ok: true, from, to: tamagotchiStage };
}

/**
 * Debug: natural / care death (hunger, health, lifespan) — NOT the AK-47 execution cinematic.
 * @param {object|null} STORAGE_KEYS
 * @param {'hunger'|'health'|'oldAge'} [cause='hunger']
 * @returns {boolean}
 */
function debugKillTamagotchiNatural(STORAGE_KEYS, cause = 'hunger') {
    const reason = ['hunger', 'health', 'oldAge'].includes(cause) ? cause : 'hunger';
    if (tamagotchiIsDead) {
        showMascotBubble('Ήδη νεκρό…', 2500);
        return false;
    }
    if (tamagotchiStage === 'egg' || tamagotchiLifeMinutes < TAMA_STAGE_MINUTES.evo1) {
        showMascotBubble('Το αυγό δεν πεθαίνει από πείνα/χρόνο ζωής.', 3000);
        return false;
    }

    cancelTamagotchiCinematics();
    clearMascotStagePreview(false);

    const keys = getTamagotchiStorageKeys(
        STORAGE_KEYS || (typeof window.STORAGE_KEYS !== 'undefined' ? window.STORAGE_KEYS : null),
    );

    if (reason === 'oldAge') {
        tamagotchiLifeMinutes = Math.max(Number(tamagotchiLifeMinutes) || 0, TAMA_STAGE_MINUTES.death);
        tamagotchiStage = 'evo3';
        tamagotchiHealth = 0;
    } else if (reason === 'health') {
        tamagotchiHealth = 0;
        tamagotchiCareMistakes = Math.max(tamagotchiCareMistakes || 0, 5);
    } else {
        petStats.hunger = 0;
        petStats.happiness = Math.min(petStats.happiness || 0, 15);
        tamagotchiHealth = 0;
        // Make starvation condition true if anything re-checks office minutes
        tamagotchiLastFed = Date.now() - (6 * 60 * 60 * 1000);
    }

    tamagotchiIsDead = true;
    if (keys) {
        recordTamagotchiNaturalDeath(keys);
        if (keys.PET_STATS) {
            GM_setValue(keys.PET_STATS, JSON.stringify(petStats));
        }
    } else {
        tamagotchiNaturalDeathCount++;
    }

    const pool = reason === 'oldAge' ? MASCOT_MESSAGES.oldAgeDeath : MASCOT_MESSAGES.death;
    showMascotBubble(pool[Math.floor(Math.random() * pool.length)], 5000);
    setMascotState(null, 'dead', 10000);
    updateDeathOptionsButton();

    const delay = reason === 'oldAge' ? 1500 : 500;
    setTimeout(() => {
        if (keys) runTamagotchiDeathSequence(keys);
    }, delay);

    console.log(`[Mascot] Debug natural death (${reason})`);
    return true;
}

function getMascotCharacterType() {
    return tamagotchiCharacterType;
}

function applyEquippedMascotAccessories(STORAGE_KEYS, stage = getEffectiveMascotStage()) {
    hideAllMascotAccessories();
    if (!STORAGE_KEYS?.EQUIPPED_ITEMS) return;

    const equipped = JSON.parse(GM_getValue(STORAGE_KEYS.EQUIPPED_ITEMS, '[]'));
    equipped.map(normalizeAccessoryId).filter(Boolean).forEach(showMascotAccessory);
    updateMascotAccessoryLayout(stage);
}

function equipMascotAccessory(config, STORAGE_KEYS, itemId) {
    const catalogItem = getAccessoryCatalogItem(itemId);
    if (!catalogItem || !STORAGE_KEYS?.EQUIPPED_ITEMS) return false;

    let equipped = JSON.parse(GM_getValue(STORAGE_KEYS.EQUIPPED_ITEMS, '[]'));
    equipped = equipped.map(normalizeAccessoryId).filter(Boolean);
    equipped = equipped.filter((id) => getAccessoryCatalogItem(id)?.slot !== catalogItem.slot);
    if (!equipped.includes(catalogItem.id)) equipped.push(catalogItem.id);

    GM_setValue(STORAGE_KEYS.EQUIPPED_ITEMS, JSON.stringify(equipped));
    applyEquippedMascotAccessories(STORAGE_KEYS);
    return true;
}

function unequipMascotAccessory(STORAGE_KEYS, itemId) {
    if (!STORAGE_KEYS?.EQUIPPED_ITEMS) return false;
    const normalized = normalizeAccessoryId(itemId);
    if (!normalized) return false;

    let equipped = JSON.parse(GM_getValue(STORAGE_KEYS.EQUIPPED_ITEMS, '[]'));
    equipped = equipped.map(normalizeAccessoryId).filter((id) => id && id !== normalized);
    GM_setValue(STORAGE_KEYS.EQUIPPED_ITEMS, JSON.stringify(equipped));
    applyEquippedMascotAccessories(STORAGE_KEYS);
    return true;
}

function toggleMascotAccessory(config, STORAGE_KEYS, itemId) {
    const normalized = normalizeAccessoryId(itemId);
    if (!normalized || !STORAGE_KEYS?.EQUIPPED_ITEMS) return false;

    const equipped = JSON.parse(GM_getValue(STORAGE_KEYS.EQUIPPED_ITEMS, '[]'))
        .map(normalizeAccessoryId)
        .filter(Boolean);

    if (equipped.includes(normalized)) {
        return unequipMascotAccessory(STORAGE_KEYS, normalized);
    }
    return equipMascotAccessory(config, STORAGE_KEYS, normalized);
}

function getShopAccessoryCatalog() {
    return MASCOT_ACCESSORY_CATALOG.map(({ slot, nameGr, ...item }) => ({
        ...item,
        type: 'accessory',
    }));
}

