/** 'full' | 'lite' | 'ultra' — auto-detected for old PCs; GM override: tm_aether_perf_mode */
let aetherPerfModeCached = null;
let aetherPerfProbeStarted = false;
let aetherPerfForcedLite = false;

function detectAetherPerfMode() {
    try {
        const forced = String(GM_getValue('tm_aether_perf_mode', '') || '').toLowerCase();
        if (forced === 'full' || forced === 'lite' || forced === 'ultra') return forced;
    } catch (_) { /* ignore */ }

    if (aetherPerfForcedLite) return 'lite';

    let reducedMotion = false;
    try {
        reducedMotion = !!window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches;
    } catch (_) { /* ignore */ }
    if (reducedMotion) return 'ultra';

    const cores = Number(navigator.hardwareConcurrency) || 4;
    const mem = Number(navigator.deviceMemory) || 8;
    const saveData = !!(navigator.connection && navigator.connection.saveData);
    const dpr = Number(window.devicePixelRatio) || 1;
    const lowEnd = cores <= 4 || mem <= 4 || saveData || dpr >= 2.5 && cores <= 6;
    if (lowEnd) return mem <= 2 || cores <= 2 ? 'ultra' : 'lite';
    return 'full';
}

function getAetherPerfMode() {
    if (!aetherPerfModeCached) aetherPerfModeCached = detectAetherPerfMode();
    return aetherPerfModeCached;
}

function isAetherLiteMode() {
    const mode = getAetherPerfMode();
    return mode === 'lite' || mode === 'ultra';
}

function isAetherUltraMode() {
    return getAetherPerfMode() === 'ultra';
}

function applyAetherPerfClass(container = document.getElementById('tm-mascot-container')) {
    if (!container) return getAetherPerfMode();
    const mode = getAetherPerfMode();
    container.classList.toggle('tm-aether-lite', mode === 'lite' || mode === 'ultra');
    container.classList.toggle('tm-aether-ultra', mode === 'ultra');
    return mode;
}

/** If frames stay slow, lock into lite for this session and re-sync FX. */
function maybeStartAetherPerfProbe() {
    if (aetherPerfProbeStarted || getAetherPerfMode() !== 'full') return;
    aetherPerfProbeStarted = true;
    let frames = 0;
    let slow = 0;
    let last = performance.now();
    const tick = (now) => {
        const dt = now - last;
        last = now;
        frames += 1;
        if (dt > 40) slow += 1;
        if (frames < 90) {
            requestAnimationFrame(tick);
            return;
        }
        if (slow / frames > 0.35) {
            aetherPerfForcedLite = true;
            aetherPerfModeCached = 'lite';
            const container = document.getElementById('tm-mascot-container');
            applyAetherPerfClass(container);
            if (tamagotchiCharacterType === 'aether' && aetherMythFxActive) {
                syncAetherMythicFx(tamagotchiStage || 'evo1');
            }
            console.log('[MMS Mascot] Aether FX switched to lite mode (slow frames).');
        }
    };
    requestAnimationFrame(tick);
}

function ensureAetherVisibilityPauseBound() {
    if (window.__tmAetherVisibilityBound) return;
    window.__tmAetherVisibilityBound = true;
    const syncHidden = () => {
        document.body.classList.toggle('tm-aether-tab-hidden', !!document.hidden);
    };
    syncHidden();
    document.addEventListener('visibilitychange', syncHidden);
}

function isAetherAwakened() {
    return Date.now() < aetherAwakenUntil;
}

/** Perf: skip heavy FX when tab hidden or too many ephemera already exist. */
function isAetherFxBudgetOk(container, maxNodes = 10) {
    if (typeof document !== 'undefined' && document.hidden) return false;
    if (!container) return false;
    if (isAetherUltraMode()) return false;
    const cap = isAetherLiteMode() ? Math.min(maxNodes, 4) : maxNodes;
    return container.querySelectorAll(
        '.tm-aether-myth-particle, .tm-aether-trail-dot, .tm-aether-shadow-twin, .tm-aether-crack-spark, .tm-aether-meteor-drip'
    ).length < cap;
}

function pruneAetherEphemera(container, keep = 8) {
    if (!container) return;
    const keepN = isAetherLiteMode() ? Math.min(keep, 3) : keep;
    const nodes = [...container.querySelectorAll(
        '.tm-aether-myth-particle, .tm-aether-trail-dot, .tm-aether-shadow-twin, .tm-aether-crack-spark'
    )];
    if (nodes.length <= keepN) return;
    nodes.slice(0, nodes.length - keepN).forEach((el) => el.remove());
}

function clearAetherTimer(refName) {
    if (refName === 'fx' && aetherMythFxTimer) { clearTimeout(aetherMythFxTimer); aetherMythFxTimer = null; }
    if (refName === 'particle' && aetherMythParticleTimer) { clearTimeout(aetherMythParticleTimer); aetherMythParticleTimer = null; }
    if (refName === 'bubble' && aetherSolemnBubbleTimer) { clearTimeout(aetherSolemnBubbleTimer); aetherSolemnBubbleTimer = null; }
    if (refName === 'trail' && aetherTrailTimer) { clearTimeout(aetherTrailTimer); aetherTrailTimer = null; }
    if (refName === 'gaze' && aetherGazeTimer) { clearTimeout(aetherGazeTimer); aetherGazeTimer = null; }
    if (refName === 'dim' && aetherDimRaf) { clearTimeout(aetherDimRaf); aetherDimRaf = null; }
    if (refName === 'blink' && aetherBlinkTimer) { clearTimeout(aetherBlinkTimer); aetherBlinkTimer = null; }
    if (refName === 'meteor' && aetherMeteorTimer) { clearTimeout(aetherMeteorTimer); aetherMeteorTimer = null; }
    if (refName === 'omen' && aetherOmenTimer) { clearTimeout(aetherOmenTimer); aetherOmenTimer = null; }
    if (refName === 'true' && aetherTrueFormTimer) { clearTimeout(aetherTrueFormTimer); aetherTrueFormTimer = null; }
    if (refName === 'heartbeat' && aetherHeartbeatTimer) { clearTimeout(aetherHeartbeatTimer); aetherHeartbeatTimer = null; }
    if (refName === 'pose' && aetherPoseTimer) { clearTimeout(aetherPoseTimer); aetherPoseTimer = null; }
    if (refName === 'twin' && aetherTwinTimer) { clearTimeout(aetherTwinTimer); aetherTwinTimer = null; }
    if (refName === 'shimmer' && aetherShimmerTimer) { clearTimeout(aetherShimmerTimer); aetherShimmerTimer = null; }
    if (refName === 'eclipse' && aetherEclipseTimer) { clearTimeout(aetherEclipseTimer); aetherEclipseTimer = null; }
    if (refName === 'throne' && aetherThroneTimer) { clearTimeout(aetherThroneTimer); aetherThroneTimer = null; }
    if (refName === 'stance' && aetherStanceTimer) { clearTimeout(aetherStanceTimer); aetherStanceTimer = null; }
    if (refName === 'truename' && aetherTrueNameTimer) { clearTimeout(aetherTrueNameTimer); aetherTrueNameTimer = null; }
    if (refName === 'starmap' && aetherStarMapTimer) { clearTimeout(aetherStarMapTimer); aetherStarMapTimer = null; }
    if (refName === 'spectacle' && aetherSpectacleTimer) { clearTimeout(aetherSpectacleTimer); aetherSpectacleTimer = null; }
    if (refName === 'screen' && aetherScreenAuraTimer) { clearTimeout(aetherScreenAuraTimer); aetherScreenAuraTimer = null; }
    if (refName === 'screenEnd' && aetherScreenAuraEndTimer) { clearTimeout(aetherScreenAuraEndTimer); aetherScreenAuraEndTimer = null; }
}

function stopAetherMythicFx() {
    aetherMythFxActive = false;
    ['fx', 'particle', 'bubble', 'trail', 'gaze', 'dim', 'blink', 'meteor', 'omen', 'true',
        'heartbeat', 'pose', 'twin', 'shimmer', 'eclipse', 'throne', 'stance', 'truename', 'starmap', 'spectacle',
        'screen', 'screenEnd']
        .forEach(clearAetherTimer);
    const container = document.getElementById('tm-mascot-container');
    if (container) {
        container.classList.remove(
            'tm-aether-glow-on', 'tm-aether-ring-on', 'tm-aether-sovereign',
            'tm-aether-react', 'tm-aether-awaken', 'tm-aether-blade-spin', 'tm-aether-gaze-on',
            'tm-aether-judgment-blink', 'tm-aether-inhale', 'tm-aether-chromatic',
            'tm-aether-scold-backlash', 'tm-aether-focus-seal', 'tm-aether-sigil-lock',
            'tm-aether-true-form', 'tm-aether-hitstop', 'tm-aether-stare',
            'tm-aether-heartbeat', 'tm-aether-pose-tilt', 'tm-aether-pose-shift', 'tm-aether-pose-flare',
            'tm-aether-domain-on', 'tm-aether-mythic-shimmer', 'tm-aether-mythic-frame',
            'tm-aether-stance-guard', 'tm-aether-stance-judgment', 'tm-aether-stance-absolute',
            'tm-aether-border-t1', 'tm-aether-border-t2', 'tm-aether-border-t3',
            'tm-aether-border-t4', 'tm-aether-border-t5', 'tm-aether-border-t6',
            'tm-aether-eclipse-iris', 'tm-aether-counter-glint'
        );
        container.querySelectorAll('.tm-aether-fx.tm-fx-on').forEach((el) => el.classList.remove('tm-fx-on'));
        container.classList.remove(
            'tm-aether-kneel-local', 'tm-aether-judgment-local', 'tm-aether-counter-glint', 'tm-aether-eclipse-iris'
        );
        container.querySelectorAll(
            '.tm-aether-myth-particle, .tm-aether-trail-dot, .tm-aether-gaze-beam, .tm-aether-crack-spark, .tm-aether-meteor-drip, .tm-aether-pet-constellation, .tm-aether-coronation-beam, .tm-aether-eye-afterimage, .tm-aether-daily-omen, .tm-aether-shadow-twin, .tm-aether-domain-circle, .tm-aether-nameplate, .tm-aether-moonshard-orbit, .tm-aether-charge-ring, .tm-aether-echo-stack, .tm-aether-throne, .tm-aether-true-name, .tm-aether-constellation-map, .tm-aether-oath-seal, .tm-aether-reality-tear, .tm-aether-astral-clone, .tm-aether-spectral-blade, .tm-aether-finisher-slash, .tm-aether-codex-scrap, .tm-aether-form-crest, .tm-aether-trail-ink, .tm-aether-rarity-ledger, .tm-aether-world-dim-local, .tm-aether-mythic-weather-local'
        ).forEach((el) => el.remove());
    }
    document.getElementById('tm-aether-world-dim')?.remove();
    document.getElementById('tm-aether-gravity-lens')?.remove();
    document.getElementById('tm-aether-mythic-weather')?.remove();
    document.getElementById('tm-aether-ambient-tint')?.remove();
    document.getElementById('tm-aether-eclipse-event')?.remove();
    document.getElementById('tm-aether-apotheosis-sky')?.remove();
    document.getElementById('tm-aether-world-nameplate')?.remove();
    clearAetherScreenAura();
    document.querySelectorAll('.tm-aether-killfeed, .tm-aether-mythic-footprint').forEach((el) => el.remove());
    document.documentElement.classList.remove('tm-aether-judgment-frame');
    document.body.classList.remove('tm-aether-kneel');
    clearAetherAmbientTint();
}

function pickRandomSubset(list, minCount, maxCount) {
    if (!list.length) return [];
    const shuffled = list.slice().sort(() => Math.random() - 0.5);
    const n = Math.min(
        list.length,
        Math.max(minCount, Math.floor(Math.random() * (maxCount - minCount + 1)) + minCount)
    );
    if (Math.random() < 0.22) return shuffled.slice(0, Math.min(1, n));
    if (Math.random() < 0.12) return [];
    return shuffled.slice(0, n);
}

function rollAetherAuraLayers(container, stage) {
    const lite = isAetherLiteMode();
    const ultra = isAetherUltraMode();
    const fullPool = AETHER_FX_BY_STAGE[stage] || AETHER_FX_BY_STAGE.baby;
    // Lite: only soft corona/aura; ultra: no SVG FX layers
    const pool = ultra
        ? []
        : lite
            ? fullPool.filter((name) => name === 'corona' || name === 'aura' || name === 'sparks')
            : fullPool;
    const tier = AETHER_STAGE_TIER[stage] || 1;
    const awakened = isAetherAwakened() && !lite;
    let active;
    if (ultra) {
        active = new Set();
    } else if (awakened) {
        active = new Set(pool);
    } else {
        const maxOn = lite
            ? Math.min(pool.length, 1)
            : Math.min(pool.length, Math.max(1, Math.ceil(tier * 0.55)));
        active = new Set(pickRandomSubset(pool, 0, maxOn));
        const moving = container.classList.contains('mascot-moving');
        if (!moving && !lite) {
            if (tier >= 3 && Math.random() < 0.55) active.add('corona');
            if (tier >= 4 && Math.random() < 0.4) active.add('orbits');
            if (tier >= 3 && Math.random() < 0.35) active.add('sigil');
            if (tier >= 4 && Math.random() < 0.25) active.add('haze');
            if (tier >= 5 && Math.random() < 0.25) active.add('fracture');
        }
        if (!lite && container.classList.contains('mascot-parked') && tier >= 3) {
            active.add('sigil');
        }
        if (lite && pool.includes('corona') && Math.random() < 0.55) active.add('corona');
    }

    container.querySelectorAll('.tm-aether-fx').forEach((el) => {
        const name = el.getAttribute('data-fx');
        el.classList.toggle('tm-fx-on', active.has(name));
    });

    const glowChance = ultra ? 0 : (awakened ? 1 : (lite ? 0.08 + tier * 0.04 : 0.12 + tier * 0.1));
    const ringChance = ultra || lite ? 0 : (awakened ? 1 : (tier >= 3 ? 0.1 + (tier - 2) * 0.1 : 0));
    container.classList.toggle('tm-aether-glow-on', Math.random() < glowChance || awakened);
    container.classList.toggle('tm-aether-ring-on', Math.random() < ringChance || awakened);
    container.classList.add('tm-aether-sovereign');
    if (!lite) syncAetherSigilLock(container);
}

function emitAetherMythParticles(container, stage, forceCount = null, { inhale = false } = {}) {
    if (!container || tamagotchiIsDead) return;
    if (isAetherUltraMode()) return;
    if (!isAetherFxBudgetOk(container, isAetherLiteMode() ? 4 : 12)) return;
    pruneAetherEphemera(container, isAetherLiteMode() ? 2 : 6);
    const lite = isAetherLiteMode();
    const tier = AETHER_STAGE_TIER[stage] || 1;
    const colors = AETHER_PARTICLE_COLORS[stage] || AETHER_PARTICLE_COLORS.adult;
    const count = forceCount != null
        ? Math.min(forceCount, lite ? 3 : 8)
        : Math.min(lite ? 2 : (2 + Math.ceil(tier * 0.8) + Math.floor(Math.random() * 2)), lite ? 3 : 7);
    const types = ['orb'];
    if (!lite && tier >= 2) types.push('star');
    if (!lite && tier >= 4) types.push('shard');

    if (inhale && !lite) container.classList.add('tm-aether-inhale');

    for (let i = 0; i < count; i++) {
        const el = document.createElement('div');
        const kind = types[Math.floor(Math.random() * types.length)];
        const color = colors[Math.floor(Math.random() * colors.length)];
        el.className = `tm-aether-myth-particle is-${kind === 'orb' ? 'orb' : kind}`;
        const angle = Math.random() * Math.PI * 2;
        const startR = 4 + Math.random() * 12;
        const endR = 24 + Math.random() * (20 + tier * 5);
        const mx = Math.cos(angle) * startR;
        const my = Math.sin(angle) * startR - 8;
        const tx = Math.cos(angle) * endR + (Math.random() * 16 - 8);
        const ty = Math.sin(angle) * endR - (24 + Math.random() * 28);
        const dur = 0.75 + Math.random() * 0.55;
        const size = kind === 'star' ? 0 : 3 + Math.random() * (2 + tier * 0.25);
        const glow = lite ? 'none' : `0 0 ${4 + tier}px ${color}`;
        el.style.cssText = `
            --mx: ${mx.toFixed(1)}px;
            --my: ${my.toFixed(1)}px;
            --tx: ${tx.toFixed(1)}px;
            --ty: ${ty.toFixed(1)}px;
            --rot: ${(80 + Math.random() * 200).toFixed(0)}deg;
            width: ${size}px;
            height: ${size}px;
            margin: ${(-size / 2).toFixed(1)}px 0 0 ${(-size / 2).toFixed(1)}px;
            background: ${color};
            color: ${color};
            box-shadow: ${glow};
            animation: ${inhale && !lite ? 'tm-aether-inhale-pull' : 'tm-aether-myth-emit'} ${dur.toFixed(2)}s cubic-bezier(0.4, 0, 0.6, 1) forwards;
        `;
        container.appendChild(el);
        setTimeout(() => el.remove(), (dur + 0.35) * 1000);
    }
    if (inhale && !lite) setTimeout(() => container.classList.remove('tm-aether-inhale'), 1000);
}

function playAetherBlackHoleInhale(container, stage) {
    if (!container) return;
    emitAetherMythParticles(container, stage, 5 + Math.min(3, AETHER_STAGE_TIER[stage] || 1), { inhale: true });
}

function emitAetherVeilTrail(container, stage) {
    if (!container || !container.classList.contains('mascot-moving')) return;
    if (container.classList.contains('mascot-parked') || mascotPositionLocked) return;
    if (!isAetherFxBudgetOk(container, 8)) return;
    const colors = AETHER_PARTICLE_COLORS[stage] || AETHER_PARTICLE_COLORS.adult;
    const color = colors[Math.floor(Math.random() * colors.length)];
    const el = document.createElement('div');
    el.className = 'tm-aether-trail-dot';
    const ox = (Math.random() * 18) - 9;
    const oy = 8 + Math.random() * 14;
    el.style.cssText = `
        left: calc(50% + ${ox.toFixed(1)}px);
        top: calc(50% + ${oy.toFixed(1)}px);
        background: ${color};
        box-shadow: 0 0 8px ${color};
        animation: tm-aether-trail-fade 0.7s cubic-bezier(0.4, 0, 0.6, 1) forwards;
    `;
    container.appendChild(el);
    setTimeout(() => el.remove(), 750);
    // Mythic trail ink (lightweight calligraphy dash) — rare while moving
    if (Math.random() < 0.08) emitAetherTrailInk(container, color);
}

/** Spawn sparks — cheap random positions (no layout reads). */
function emitAetherWingCrackSparks(container, stage, count = 2) {
    if (!container || !isAetherFxBudgetOk(container, 10)) return;
    const colors = AETHER_PARTICLE_COLORS[stage] || AETHER_PARTICLE_COLORS.adult;
    const n = Math.min(count, 3);
    for (let i = 0; i < n; i++) {
        const color = colors[Math.floor(Math.random() * colors.length)];
        const el = document.createElement('div');
        el.className = 'tm-aether-crack-spark';
        const sx = 18 + Math.random() * 64;
        const sy = 22 + Math.random() * 40;
        el.style.cssText = `
            left: ${sx.toFixed(1)}%;
            top: ${sy.toFixed(1)}%;
            background: ${color};
            box-shadow: 0 0 6px ${color};
            --cx: ${(Math.random() * 20 - 6).toFixed(1)}px;
            --cy: ${(-8 - Math.random() * 18).toFixed(1)}px;
        `;
        container.appendChild(el);
        setTimeout(() => el.remove(), 650);
    }
}

function emitAetherMeteorDrip(container, stage) {
    if (!container || !isAetherFxBudgetOk(container, isAetherLiteMode() ? 4 : 10)) return;
    // Cheap random wing-side drip — avoid getBoundingClientRect layout thrash
    const colors = AETHER_PARTICLE_COLORS[stage] || AETHER_PARTICLE_COLORS.adult;
    const el = document.createElement('div');
    el.className = 'tm-aether-meteor-drip';
    const color = colors[Math.floor(Math.random() * colors.length)];
    const leftSide = Math.random() < 0.5;
    const sx = leftSide ? (12 + Math.random() * 18) : (70 + Math.random() * 18);
    const sy = 22 + Math.random() * 28;
    el.style.cssText = `
        left: ${sx.toFixed(1)}%;
        top: ${sy.toFixed(1)}%;
        background: linear-gradient(to bottom, ${color}, transparent);
        box-shadow: ${isAetherLiteMode() ? 'none' : `0 0 8px ${color}`};
    `;
    container.appendChild(el);
    setTimeout(() => el.remove(), 1200);
}

function playAetherGazeBeam(container, stage) {
    if (!container) return;
    container.querySelectorAll('.tm-aether-gaze-beam').forEach((el) => el.remove());
    container.classList.add('tm-aether-gaze-on', 'tm-aether-stare');
    const colors = AETHER_PARTICLE_COLORS[stage] || AETHER_PARTICLE_COLORS.adult;
    const eyeY = stage === 'evo1' ? 42 : stage === 'evo3' ? 28 : 32;
    const leftX = 42;
    const rightX = 58;
    const angles = [-18 - Math.random() * 10, 18 + Math.random() * 10];
    [
        { x: leftX, cls: '' },
        { x: rightX, cls: 'is-right' },
    ].forEach((eye, i) => {
        const beam = document.createElement('div');
        beam.className = `tm-aether-gaze-beam ${eye.cls}`.trim();
        beam.style.cssText = `
            left: ${eye.x}%;
            top: ${eyeY}%;
            transform: rotate(${angles[i].toFixed(1)}deg);
            background: linear-gradient(to bottom, ${colors[0]}, ${colors[2] || colors[1]}, transparent);
        `;
        container.appendChild(beam);
        setTimeout(() => beam.remove(), 1700);

        const ghost = document.createElement('div');
        ghost.className = 'tm-aether-eye-afterimage';
        ghost.style.cssText = `
            left: ${eye.x}%;
            top: ${eyeY}%;
            --dx: ${(i === 0 ? -10 : 10).toFixed(0)}px;
            background: radial-gradient(circle, ${colors[1]}aa, transparent 70%);
        `;
        container.appendChild(ghost);
        setTimeout(() => ghost.remove(), 900);
    });
    playAetherJudgmentFrame(50);
    // Solar eclipse iris — CSS class only (no extra DOM)
    container.classList.add('tm-aether-eclipse-iris');
    setTimeout(() => container.classList.remove('tm-aether-eclipse-iris'), 900);
    setTimeout(() => container.classList.remove('tm-aether-gaze-on', 'tm-aether-stare'), 1400);
}

function playAetherBlinkOfJudgment(container, stage) {
    if (!container) return;
    container.classList.add('tm-aether-judgment-blink', 'tm-aether-glow-on');
    // Peak set only — never force every blurred FX layer on
    const peak = new Set(['corona', 'aura', 'sparks', 'sigil']);
    if (!isAetherLiteMode() && (AETHER_STAGE_TIER[stage] || 1) >= 4) peak.add('haze');
    container.querySelectorAll('.tm-aether-fx').forEach((el) => {
        const name = el.getAttribute('data-fx');
        el.classList.toggle('tm-fx-on', peak.has(name));
    });
    emitAetherMythParticles(container, stage, isAetherLiteMode() ? 3 : 5);
    syncAetherScreenAura(container, stage, peak);
    setTimeout(() => {
        container.classList.remove('tm-aether-judgment-blink');
        if (aetherMythFxActive) rollAetherAuraLayers(container, stage || tamagotchiStage || 'evo2');
    }, 700);
}

const AETHER_SCREEN_AURA_STAGE = {
    baby: { c1: '126,200,195', c2: '201,160,220', c3: '255,224,130' },
    kid: { c1: '77,182,172', c2: '149,117,205', c3: '255,183,77' },
    teen: { c1: '0,172,193', c2: '92,107,192', c3: '192,160,96' },
    adult: { c1: '38,198,218', c2: '124,77,255', c3: '255,213,79' },
    middleage: { c1: '239,83,80', c2: '106,27,154', c3: '191,143,46' },
    old: { c1: '139,0,0', c2: '93,64,55', c3: '201,184,150' },
};

let aetherScreenAuraOriginTimer = null;
let aetherScreenAuraTimer = null;
let aetherScreenAuraEndTimer = null;
let aetherScreenAuraUntil = 0;

function clearAetherScreenAura() {
    if (aetherScreenAuraOriginTimer) {
        clearTimeout(aetherScreenAuraOriginTimer);
        aetherScreenAuraOriginTimer = null;
    }
    if (aetherScreenAuraEndTimer) {
        clearTimeout(aetherScreenAuraEndTimer);
        aetherScreenAuraEndTimer = null;
    }
    aetherScreenAuraUntil = 0;
    document.getElementById('tm-aether-screen-aura')?.remove();
    document.getElementById('tm-aether-world-dim')?.remove();
    document.getElementById('tm-aether-gravity-lens')?.remove();
    document.body.classList.remove('tm-aether-screen-aura-on');
}

function hideAetherScreenAura() {
    aetherScreenAuraUntil = 0;
    if (aetherScreenAuraEndTimer) {
        clearTimeout(aetherScreenAuraEndTimer);
        aetherScreenAuraEndTimer = null;
    }
    if (aetherScreenAuraOriginTimer) {
        clearTimeout(aetherScreenAuraOriginTimer);
        aetherScreenAuraOriginTimer = null;
    }
    const root = document.getElementById('tm-aether-screen-aura');
    const dim = document.getElementById('tm-aether-world-dim');
    root?.classList.remove('is-on', 'is-strong', 'is-awaken', 'has-ring', 'has-haze', 'has-rays');
    document.body.classList.remove('tm-aether-screen-aura-on');
    if (dim) dim.style.opacity = '0';
    setTimeout(() => {
        if (Date.now() < aetherScreenAuraUntil) return;
        document.getElementById('tm-aether-screen-aura')?.remove();
        document.getElementById('tm-aether-world-dim')?.remove();
    }, 700);
}

function ensureAetherScreenAura() {
    let root = document.getElementById('tm-aether-screen-aura');
    if (root) return root;
    root = document.createElement('div');
    root.id = 'tm-aether-screen-aura';
    root.setAttribute('aria-hidden', 'true');
    root.innerHTML = `
        <div class="tm-aether-screen-veil"></div>
        <div class="tm-aether-screen-bloom"></div>
        <div class="tm-aether-screen-ring"></div>
        <div class="tm-aether-screen-haze"></div>
        <div class="tm-aether-screen-rays"></div>
    `;
    document.body.appendChild(root);
    return root;
}

function updateAetherScreenAuraOrigin(container = document.getElementById('tm-mascot-container')) {
    const root = document.getElementById('tm-aether-screen-aura');
    if (!root || !container) return;
    const r = container.getBoundingClientRect();
    const ax = Math.round(r.left + r.width / 2);
    const ay = Math.round(r.top + r.height / 2);
    const axp = `${((ax / Math.max(1, window.innerWidth)) * 100).toFixed(2)}%`;
    const ayp = `${((ay / Math.max(1, window.innerHeight)) * 100).toFixed(2)}%`;
    root.style.setProperty('--ax', `${ax}px`);
    root.style.setProperty('--ay', `${ay}px`);
    root.style.setProperty('--axp', axp);
    root.style.setProperty('--ayp', ayp);
    const dim = document.getElementById('tm-aether-world-dim');
    if (dim) {
        dim.style.setProperty('--ax', `${ax}px`);
        dim.style.setProperty('--ay', `${ay}px`);
        dim.style.setProperty('--axp', axp);
        dim.style.setProperty('--ayp', ayp);
    }
}

function scheduleAetherScreenAuraOrigin(container) {
    if (aetherScreenAuraOriginTimer) return;
    const tick = () => {
        aetherScreenAuraOriginTimer = null;
        if (!aetherMythFxActive || Date.now() >= aetherScreenAuraUntil) return;
        if (!document.getElementById('tm-aether-screen-aura')) return;
        updateAetherScreenAuraOrigin(container);
        aetherScreenAuraOriginTimer = setTimeout(tick, document.hidden ? 2500 : 700);
    };
    aetherScreenAuraOriginTimer = setTimeout(tick, 80);
}

/** Soft vignette only while a screen-aura burst is live. */
function updateAetherWorldDim(container, stage, { strengthOverride = null } = {}) {
    document.getElementById('tm-aether-gravity-lens')?.remove();
    container?.querySelectorAll('.tm-aether-world-dim-local').forEach((el) => el.remove());

    if (!aetherMythFxActive || !container || isAetherUltraMode() || Date.now() >= aetherScreenAuraUntil) {
        const dim = document.getElementById('tm-aether-world-dim');
        if (dim) dim.style.opacity = '0';
        return;
    }

    const liveStage = stage || tamagotchiStage || 'evo2';
    const tier = AETHER_STAGE_TIER[liveStage] || 1;
    const awakened = isAetherAwakened();
    const lite = isAetherLiteMode();
    const strengthByTier = { 1: 0.1, 2: 0.12, 3: 0.14, 4: 0.16, 5: 0.2, 6: 0.24 };
    const strength = strengthOverride != null
        ? strengthOverride
        : (awakened ? (lite ? 0.26 : 0.32) : (strengthByTier[tier] ?? 0.12) * (lite ? 0.7 : 1));

    let dim = document.getElementById('tm-aether-world-dim');
    if (!dim) {
        dim = document.createElement('div');
        dim.id = 'tm-aether-world-dim';
        dim.setAttribute('aria-hidden', 'true');
        document.body.appendChild(dim);
    }
    dim.className = `tm-aether-dim-t${awakened ? 6 : tier}${awakened || tier >= 6 ? ' tm-aether-dim-strong' : ''}${lite ? ' is-lite' : ''}`;
    dim.style.opacity = String(strength);
    updateAetherScreenAuraOrigin(container);
}

function updateAetherGravityLens() {
    document.getElementById('tm-aether-gravity-lens')?.remove();
}

/**
 * Short random fullscreen aura flash (~1.2–2.6s). Not always on.
 */
function playAetherScreenAuraBurst(container, stage, {
    activeFx = null,
    durationMs = null,
    force = false,
} = {}) {
    if (!aetherMythFxActive || !container || tamagotchiCharacterType !== 'aether' || tamagotchiIsDead) {
        return false;
    }
    if (isAetherUltraMode()) return false;
    if (document.hidden && !force) return false;

    const liveStage = stage || tamagotchiStage || 'evo2';
    const tier = AETHER_STAGE_TIER[liveStage] || 1;
    const lite = isAetherLiteMode();
    const awakened = isAetherAwakened();
    const colors = AETHER_SCREEN_AURA_STAGE[liveStage] || AETHER_SCREEN_AURA_STAGE.adult;

    const hold = Math.max(
        900,
        Math.min(
            force || awakened ? 3000 : 2400,
            durationMs != null
                ? durationMs
                : (lite ? 1000 + Math.random() * 800 : 1200 + Math.random() * 1200)
                    + (awakened ? 350 : 0)
        )
    );

    const fx = activeFx || new Set(
        [...container.querySelectorAll('.tm-aether-fx.tm-fx-on')]
            .map((el) => el.getAttribute('data-fx'))
            .filter(Boolean)
    );
    const glowOn = container.classList.contains('tm-aether-glow-on') || force || awakened;
    const ringOn = container.classList.contains('tm-aether-ring-on')
        || fx.has('corona')
        || (!lite && Math.random() < 0.45);
    const hasHaze = !lite && (fx.has('haze') || fx.has('aura-outer') || awakened || Math.random() < 0.35);
    const hasBeams = !lite && (fx.has('beams') || fx.has('orbits') || awakened || Math.random() < 0.25);

    const root = ensureAetherScreenAura();
    root.dataset.stage = liveStage;
    root.style.setProperty('--ac1', colors.c1);
    root.style.setProperty('--ac2', colors.c2);
    root.style.setProperty('--ac3', colors.c3);

    const strength = Math.min(
        1,
        (lite ? 0.28 : 0.32)
            + tier * 0.04
            + (glowOn ? 0.1 : 0)
            + (fx.has('aura') ? 0.08 : 0)
            + (fx.has('corona') ? 0.06 : 0)
            + (awakened ? 0.18 : 0)
            + (force ? 0.12 : 0)
    );
    root.style.setProperty('--aura-strength', strength.toFixed(3));

    root.classList.toggle('is-lite', lite);
    root.classList.toggle('is-strong', strength > 0.5 || tier >= 5 || force);
    root.classList.toggle('is-awaken', awakened || force);
    root.classList.toggle('has-ring', ringOn);
    root.classList.toggle('has-haze', hasHaze);
    root.classList.toggle('has-rays', hasBeams);
    root.classList.add('is-on');
    document.body.classList.add('tm-aether-screen-aura-on');

    aetherScreenAuraUntil = Date.now() + hold;
    updateAetherScreenAuraOrigin(container);
    scheduleAetherScreenAuraOrigin(container);
    updateAetherWorldDim(container, liveStage, { strengthOverride: strength * 0.55 });

    if (aetherScreenAuraEndTimer) clearTimeout(aetherScreenAuraEndTimer);
    aetherScreenAuraEndTimer = setTimeout(() => {
        aetherScreenAuraEndTimer = null;
        hideAetherScreenAura();
    }, hold);

    return true;
}

/** Alias used by blink/awaken — always a short burst. */
function syncAetherScreenAura(container, stage, activeFx = null) {
    playAetherScreenAuraBurst(container, stage, {
        activeFx,
        durationMs: 1600 + Math.random() * 600,
        force: true,
    });
}

function scheduleAetherScreenAuraBursts(container, stage) {
    if (!aetherMythFxActive || isAetherUltraMode()) return;
    clearAetherTimer('screen');
    const lite = isAetherLiteMode();
    const tier = AETHER_STAGE_TIER[stage] || 1;
    const waitMs = (lite ? 18000 : 12000)
        + Math.random() * (lite ? 22000 : 18000)
        - Math.min(4000, tier * 500);

    aetherScreenAuraTimer = setTimeout(() => {
        aetherScreenAuraTimer = null;
        if (!aetherMythFxActive) return;
        const live = document.getElementById('tm-mascot-container') || container;
        const liveStage = (typeof tamagotchiStage !== 'undefined' && tamagotchiStage) ? tamagotchiStage : stage;
        const chance = lite ? 0.4 : (0.48 + tier * 0.04);
        if (!document.hidden && !isMascotFocusQuiet() && Math.random() < chance) {
            playAetherScreenAuraBurst(live, liveStage);
        }
        scheduleAetherScreenAuraBursts(live, liveStage);
    }, Math.max(9000, waitMs));
}

function scheduleAetherWorldDim() {
    // World dim only rides along with short screen-aura bursts
    clearAetherTimer('dim');
}

function scheduleAetherAuraRoll(container, stage) {
    if (!aetherMythFxActive) return;
    const tier = AETHER_STAGE_TIER[stage] || 1;
    const lite = isAetherLiteMode();
    const holdMs = isAetherAwakened() && !lite
        ? 2200
        : (lite ? 9000 : 4200) + Math.random() * (lite ? 8000 : (3800 + tier * 500));
    aetherMythFxTimer = setTimeout(() => {
        if (!aetherMythFxActive) return;
        if (!document.hidden) rollAetherAuraLayers(container, stage);
        scheduleAetherAuraRoll(container, stage);
    }, holdMs);
}

function scheduleAetherParticleBurst(container, stage) {
    if (!aetherMythFxActive) return;
    if (isAetherUltraMode()) return;
    const tier = AETHER_STAGE_TIER[stage] || 1;
    const lite = isAetherLiteMode();
    const waitMs = isAetherAwakened() && !lite
        ? 2800 + Math.random() * 1800
        : (lite ? 14000 : 7000) + Math.random() * (lite ? 16000 : (9000 - tier * 300));
    aetherMythParticleTimer = setTimeout(() => {
        if (!aetherMythFxActive) return;
        if (!document.hidden && (isAetherAwakened() || Math.random() > (lite ? 0.78 : 0.62))) {
            if (!lite && tier >= 4 && Math.random() < 0.12) {
                playAetherBlackHoleInhale(container, stage);
            } else {
                emitAetherMythParticles(container, stage, isAetherAwakened() && !lite ? 4 + Math.min(2, tier) : null);
            }
            if (!lite && (isAetherAwakened() || Math.random() < 0.12)) {
                emitAetherWingCrackSparks(container, stage, 1);
            }
        }
        scheduleAetherParticleBurst(container, stage);
    }, Math.max(lite ? 8000 : 2400, waitMs));
}

