function clearAetherAmbientTint() {
    document.body.classList.remove(
        'tm-aether-ambient-on',
        'tm-aether-ambient-baby', 'tm-aether-ambient-kid', 'tm-aether-ambient-teen',
        'tm-aether-ambient-adult', 'tm-aether-ambient-middleage', 'tm-aether-ambient-old'
    );
    aetherAmbientStage = '';
    document.getElementById('tm-aether-ambient-tint')?.remove();
    try {
        document.body.style.removeProperty('--aether-ambient');
        document.body.style.removeProperty('--ax');
        document.body.style.removeProperty('--ay');
    } catch (_) { /* ignore */ }
}

function updateAetherAmbientTint(container, stage) {
    if (!aetherMythFxActive || !container || isAetherUltraMode()) {
        clearAetherAmbientTint();
        return;
    }
    const liveStage = stage || tamagotchiStage || 'evo2';
    const stages = ['evo1', 'evo2', 'evo3'];
    document.body.classList.remove(
        'tm-aether-ambient-baby', 'tm-aether-ambient-kid', 'tm-aether-ambient-teen',
        'tm-aether-ambient-adult', 'tm-aether-ambient-middleage', 'tm-aether-ambient-old'
    );
    if (stages.includes(liveStage)) {
        document.body.classList.add('tm-aether-ambient-on', `tm-aether-ambient-${liveStage}`);
        aetherAmbientStage = liveStage;
    }
    // Fullscreen wash is random/short — do not keep it on from ambient sync
}

